using Bliss.Domain.CommandGateway;
namespace Bliss.Tests.CommandGateway;
public sealed class GatewayRepositoryContractTests
{
 private static readonly Guid Tenant=Guid.NewGuid(),Engineer=Guid.NewGuid();
 private const string Base="0123456789abcdef0123456789abcdef01234567",Head="89abcdef0123456789abcdef0123456789abcdef",Artifact="AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA";
 private static GatewayPrincipal Principal()=>new(true,Tenant,Engineer);
 private static GatewayRepositoryPolicy Policy()=>new(true,Tenant,Engineer,"Coxskull/Bliss_Bot_Chapel","main",new HashSet<string>{"Bliss.Domain/CommandGateway/","Bliss.Tests/CommandGateway/","docs/command-gateway/"},new HashSet<string>{"release-build","gateway-tests","dependency-audit"},12);
 private static GatewayChangeProposal Proposal(params string[] paths)=>new("Coxskull/Bliss_Bot_Chapel","main",Base,"feature/agm-a2a-005",Head,paths.Length==0?["Bliss.Domain/CommandGateway/Example.cs"]:paths);
 private static GatewayCiEvidence Evidence(string head=Head,params GatewayCiCheck[] checks)=>new("Coxskull/Bliss_Bot_Chapel",head,Artifact,checks.Length==0?[new("gateway-tests","SUCCESS"),new("dependency-audit","SUCCESS"),new("release-build","SUCCESS")]:checks);
 [Fact]public void Exact_repository_paths_head_and_checks_create_human_review_only()
 {var result=GatewayRepositoryContract.Validate(Principal(),Policy(),Proposal(),Evidence());Assert.True(result.ReadyForHumanReview);Assert.False(result.ApprovalGranted);Assert.False(result.MergeAuthorized);Assert.False(result.DeploymentAuthorized);Assert.False(result.ToolExecutionAuthorized);Assert.Equal(Head,result.HeadSha);Assert.Equal(Artifact,result.ArtifactSha256);}
 [Fact]public void Authentication_tenant_actor_repository_and_base_are_exact()
 {Assert.Throws<UnauthorizedAccessException>(()=>GatewayRepositoryContract.Validate(Principal() with{Authenticated=false},Policy(),Proposal(),Evidence()));Assert.Throws<UnauthorizedAccessException>(()=>GatewayRepositoryContract.Validate(Principal() with{TenantId=Guid.NewGuid()},Policy(),Proposal(),Evidence()));Assert.Throws<UnauthorizedAccessException>(()=>GatewayRepositoryContract.Validate(Principal(),Policy() with{AgentId=Guid.NewGuid()},Proposal(),Evidence()));Assert.Throws<UnauthorizedAccessException>(()=>GatewayRepositoryContract.Validate(Principal(),Policy(),Proposal() with{Repository="Coxskull/other"},Evidence()));Assert.Throws<UnauthorizedAccessException>(()=>GatewayRepositoryContract.Validate(Principal(),Policy(),Proposal() with{BaseBranch="release"},Evidence()));}
 [Fact]public void Workflow_deployment_infrastructure_secrets_and_path_traversal_are_refused()
 {foreach(var path in new[]{".github/workflows/deploy.yml","deploy/app.yml","infra/main.tf","k8s/app.yml","Bliss.Domain/CommandGateway/.env","Bliss.Domain/CommandGateway/signing.key","Bliss.Domain/CommandGateway/../Api/Program.cs","/Bliss.Domain/CommandGateway/X.cs"})Assert.ThrowsAny<Exception>(()=>GatewayRepositoryContract.Validate(Principal(),Policy(),Proposal(path),Evidence()));}
 [Fact]public void Outside_duplicate_empty_and_unbounded_changes_are_refused()
 {Assert.Throws<UnauthorizedAccessException>(()=>GatewayRepositoryContract.Validate(Principal(),Policy(),Proposal("Bliss.Api/Program.cs"),Evidence()));Assert.Throws<ArgumentException>(()=>GatewayRepositoryContract.Validate(Principal(),Policy(),Proposal("Bliss.Domain/CommandGateway/X.cs","Bliss.Domain/CommandGateway/X.cs"),Evidence()));Assert.Throws<ArgumentException>(()=>GatewayRepositoryContract.Validate(Principal(),Policy(),Proposal(Enumerable.Range(0,13).Select(i=>$"Bliss.Domain/CommandGateway/X{i}.cs").ToArray()),Evidence()));}
 [Fact]public void Wrong_head_missing_duplicate_failed_extra_checks_and_bad_artifact_are_refused()
 {Assert.Throws<ArgumentException>(()=>GatewayRepositoryContract.Validate(Principal(),Policy(),Proposal(),Evidence(new string('a',40))));Assert.Throws<InvalidOperationException>(()=>GatewayRepositoryContract.Validate(Principal(),Policy(),Proposal(),Evidence(Head,new GatewayCiCheck("release-build","SUCCESS"))));Assert.Throws<InvalidOperationException>(()=>GatewayRepositoryContract.Validate(Principal(),Policy(),Proposal(),Evidence(Head,new GatewayCiCheck("release-build","SUCCESS"),new GatewayCiCheck("release-build","SUCCESS"),new GatewayCiCheck("gateway-tests","SUCCESS"))));Assert.Throws<InvalidOperationException>(()=>GatewayRepositoryContract.Validate(Principal(),Policy(),Proposal(),Evidence(Head,new GatewayCiCheck("release-build","FAILURE"),new GatewayCiCheck("gateway-tests","SUCCESS"),new GatewayCiCheck("dependency-audit","SUCCESS"))));Assert.Throws<InvalidOperationException>(()=>GatewayRepositoryContract.Validate(Principal(),Policy(),Proposal(),Evidence(Head,new GatewayCiCheck("release-build","SUCCESS"),new GatewayCiCheck("gateway-tests","SUCCESS"),new GatewayCiCheck("dependency-audit","SUCCESS"),new GatewayCiCheck("deploy","SUCCESS"))));Assert.Throws<ArgumentException>(()=>GatewayRepositoryContract.Validate(Principal(),Policy(),Proposal(),Evidence() with{ArtifactSha256="bad"}));}
 [Fact]public void Branch_hash_policy_and_check_bounds_are_refused()
 {Assert.Throws<ArgumentException>(()=>GatewayRepositoryContract.Validate(Principal(),Policy(),Proposal() with{HeadBranch="main"},Evidence()));Assert.Throws<ArgumentException>(()=>GatewayRepositoryContract.Validate(Principal(),Policy(),Proposal() with{HeadSha=Base},Evidence(Base)));Assert.Throws<ArgumentException>(()=>GatewayRepositoryContract.Validate(Principal(),Policy() with{MaxChangedFiles=0},Proposal(),Evidence()));Assert.Throws<ArgumentException>(()=>GatewayRepositoryContract.Validate(Principal(),Policy() with{RequiredChecks=new HashSet<string>()},Proposal(),Evidence()));}
}
